CREATE OR REPLACE DYNAMIC TABLE AGG.AGG_SERVICE_REQUEST_DAY_STATUS_SEGMENT
  TARGET_LAG = '24 hours'
  WAREHOUSE  = WH_SEMANTIC_REFRESH
  COMMENT = 'Demand-driven aggregate of FCT_SERVICE_REQUEST at grain Date.FiscalYear, Date.FullDate, Date.MonthName, Date.Quarter, Customer.CustomerSegment, ServiceRequest.RequestType, ServiceRequest.Status, Date.MonthNumber; covers 26.81% of weighted demand (4 clusters); est. 528,000 rows; ~0.0167 credits/day'
AS
SELECT d1.FISCAL_YEAR,
       d1.FULL_DATE,
       d1.MONTH_NAME,
       d1.QUARTER,
       c2.CUSTOMER_SEGMENT,
       f.REQUEST_TYPE,
       f.STATUS,
       d1.MONTH_NUMBER,
       COUNT(*) AS SERVICE_REQUEST_COUNT
FROM CORE.FCT_SERVICE_REQUEST f
JOIN CORE.DIM_DATE d1 ON f.DATE_KEY = d1.DATE_KEY
JOIN CORE.DIM_CUSTOMER c2 ON f.CUSTOMER_ID = c2.CUSTOMER_ID
GROUP BY ALL;
